def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()
    write_times = {}
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries
            expired_keys = [k for k, write_t in write_times.items() 
                          if write_t + ttl <= t]
            for k in expired_keys:
                if k in cache:
                    del cache[k]
                    del write_times[k]

            # If key already exists, remove it to re-insert it at the end
            if key in cache:
                del cache[key]

            # If cache is full, evict LRU
            if len(cache) >= capacity:
                lru_key = next(iter(cache))
                del cache[lru_key]
                del write_times[lru_key]

            # Add new entry
            cache[key] = value
            write_times[key] = t

        elif op[0] == 'get':
            _, t, key = op

            # Remove expired entries
            expired_keys = [k for k, write_t in write_times.items() 
                          if write_t + ttl <= t]
            for k in expired_keys:
                if k in cache:
                    del cache[k]
                    del write_times[k]

            # Get the value
            if key in cache:
                results.append(cache[key])
                # Move to end (most recently used)
                cache.move_to_end(key)
            else:
                results.append(-1)

    return results

